script:
frappe.ui.form.on('Customer', {
    refresh: function(frm) {
        $("[data-label='View']").hide();

        // Existing Login Button
        if (!frm.is_new()) {
            frm.add_custom_button(__('Login as Customer'), function() {
                frappe.prompt([
                    {
                        label: 'Select Portal',
                        fieldname: 'portal',
                        fieldtype: 'Select',
                        options: ['Cotton Valley', 'UDC'],
                        reqd: 1
                    }
                ],
                function(values){
                    if(values.portal === 'Cotton Valley') {
                        let email = frm.doc.custom_user;
                        let password = frm.doc.custom_password;
                        if(!email || !password) {
                            frappe.msgprint(__('Please set Email and Password for this customer.'));
                            return;
                        }

                        // Create hidden form and submit via POST
                        let form = document.createElement("form");
                        form.method = "POST";
                        form.action = "http://156.67.27.94:3001/en/auth/login";
                        form.target = "_blank"; // open in new tab

                        let emailField = document.createElement("input");
                        emailField.type = "hidden";
                        emailField.name = "email";
                        emailField.value = email;

                        let passwordField = document.createElement("input");
                        passwordField.type = "hidden";
                        passwordField.name = "password";
                        passwordField.value = password;

                        form.appendChild(emailField);
                        form.appendChild(passwordField);
                        document.body.appendChild(form);
                        form.submit();
                        document.body.removeChild(form);

                    } else {
                        frappe.msgprint(__('UDC login flow not implemented yet.'));
                    }
                },
                __('Login Options'),
                __('Next')
                )
            });
        }
    },

    validate: function(frm) {
        if (frm.doc.password !== frm.doc.confirm_password) {
            frappe.throw(__('Password and Confirm Password must be the same'));
        }
    }
});

frappe.listview_settings['Customer'] = {
    onload(listview) {
        // Hide sidebar
        $('.layout-side-section').hide();
        // Add "Product" button
        listview.page.add_inner_button('Product', () => {
            frappe.set_route("List", "Item");  // Opens Product (Item) list
        });

        // Add "Sales Reps" button
        listview.page.add_inner_button('Sales Reps', () => {
            frappe.set_route("List", "Sales Person");  // Opens Sales Reps list
        });
    }
};

frappe.ui.form.on("Address", {
  pincode: async function(frm) {
    const zip = frm.doc.pincode;

    if (!zip) return;

    try {
      // Free API (works for many countries, e.g. US, CA, GB, etc.)
      const res = await fetch(`https://api.zippopotam.us/us/${zip}`);

      if (!res.ok) {
        frappe.msgprint("No data found for this postal code.");
        return;
      }

      const data = await res.json();
    console.log(data)
      if (data.places && data.places.length > 0) {
        const place = data.places[0];

        frm.set_value("city", place["place name"]);
        frm.set_value("state", place["state"]);
        frm.set_value("country", data["country"]);
      }
    } catch (e) {
      console.error("Postal lookup error:", e);
      frappe.msgprint("Could not fetch location details.");
    }
  }
});
